// Primeiro filtro funcional: confere para qual número da empresa a mensagem foi enviada.
// Este node apenas lê metadata.display_phone_number; não altera o payload recebido.
const entrada = $('Normalizar Evolution para contrato legado').first().json;
const corpo = entrada.body ?? entrada;
const displayPhoneNumber = String(
  corpo.entry?.[0]?.changes?.[0]?.value?.metadata?.display_phone_number ?? ''
).trim();

// Comparamos apenas os dígitos para aceitar o valor com ou sem espaços, hífen e sinal de +.
const numeroRecebido = displayPhoneNumber.replace(/\D/g, '');
const variaveis = $('Variaveis de producao').first().json;
const numeroAutorizado = String(variaveis.numero_destinatario_autorizado ?? '').replace(/\D/g, '');
const permitido = numeroRecebido === numeroAutorizado;

return [{
  json: {
    permitido,
    display_phone_number: displayPhoneNumber,
    numero_normalizado: numeroRecebido,
    codigo: permitido ? 'NUMERO_DESTINATARIO_AUTORIZADO' : 'NUMERO_DESTINATARIO_IGNORADO'
  }
}];

// O CRM repassa o JSON da Meta sem alterar seu conteudo.
// Esta etapa aceita texto, audio, imagem, documento e respostas de botao/lista; a interpretacao de midia fica no EV-13.
const entrada = $('Normalizar Evolution para contrato legado').first().json;
const corpo = entrada.body ?? entrada;
const headers = entrada.headers ?? {};
const variaveis = $('Variaveis de producao').first().json;
const avaliacaoBotaoPrefixo = String(variaveis.avaliacao_botao_prefixo ?? '').trim();
const transferenciaListaPrefixo = String(variaveis.transferencia_lista_atendente_prefixo ?? '').trim();
const followupBotaoSimId = String(variaveis.followup_botao_sim_id ?? '').trim();
const followupBotaoNaoId = String(variaveis.followup_botao_nao_id ?? '').trim();

const value = corpo.entry?.[0]?.changes?.[0]?.value ?? {};
const mensagem = value.messages?.[0] ?? null;
const contato = value.contacts?.[0] ?? {};
const atendimentoId = headers['x-crm-atendimento-id'] ?? headers['X-CRM-Atendimento-Id'] ?? '';
const leadId = headers['x-crm-lead-id'] ?? headers['X-CRM-Lead-Id'] ?? '';

if (!mensagem?.id) {
  return [{ json: { processar: false, resposta: { aceito: true, codigo: 'EVENTO_META_SEM_MENSAGEM' } } }];
}

const tipoMeta = String(mensagem.type ?? '').toLowerCase();
const interactive = mensagem.interactive ?? {};
const buttonReply = interactive.button_reply ?? {};
const listReply = interactive.list_reply ?? {};
const legacyButton = mensagem.button ?? {};
const respostaBotao = tipoMeta === 'interactive' && interactive.type === 'button_reply'
  ? { id: String(buttonReply.id ?? '').trim(), titulo: String(buttonReply.title ?? '').trim(), origem: 'interactive.button_reply' }
  : (tipoMeta === 'button'
    ? { id: String(legacyButton.payload ?? '').trim(), titulo: String(legacyButton.text ?? '').trim(), origem: 'button' }
    : null);
const respostaLista = tipoMeta === 'interactive' && interactive.type === 'list_reply'
  ? { id: String(listReply.id ?? '').trim(), titulo: String(listReply.title ?? '').trim(), descricao: String(listReply.description ?? '').trim(), origem: 'interactive.list_reply' }
  : null;
const transferenciaListaResposta = respostaLista && transferenciaListaPrefixo && respostaLista.id.startsWith(transferenciaListaPrefixo)
  ? {
    atendente_id: respostaLista.id.slice(transferenciaListaPrefixo.length),
    titulo: respostaLista.titulo,
    descricao: respostaLista.descricao,
    origem: respostaLista.origem
  }
  : null;
const followupResposta = respostaBotao && [followupBotaoSimId, followupBotaoNaoId].filter(Boolean).includes(respostaBotao.id)
  ? {
    decisao: respostaBotao.id === followupBotaoNaoId ? 'NAO' : 'SIM',
    id: respostaBotao.id,
    titulo: respostaBotao.titulo,
    origem: respostaBotao.origem
  }
  : null;

const mapaTipos = { text: 'TEXTO', conversation: 'TEXTO', interactive: 'TEXTO', button: 'TEXTO', audio: 'AUDIO', image: 'IMAGEM', document: 'DOCUMENTO' };
const tipo = mapaTipos[tipoMeta] ?? String(tipoMeta).toUpperCase();
const conteudo = mensagem[tipoMeta] ?? {};
const textoInterativo = respostaBotao ? (respostaBotao.titulo || respostaBotao.id) : (respostaLista ? (respostaLista.titulo || respostaLista.id) : '');
const texto = String(textoInterativo || mensagem.text?.body || conteudo.caption || '').replace(/\s+/g, ' ').trim();
const mediaId = String(conteudo.id ?? '').trim();
const tipoSuportado = ['TEXTO', 'AUDIO', 'IMAGEM', 'DOCUMENTO'].includes(tipo);

if (!tipoSuportado) {
  return [{ json: { processar: false, resposta: { aceito: true, codigo: 'MENSAGEM_TIPO_NAO_SUPORTADO', tipo } } }];
}
if (tipo === 'TEXTO' && !texto) {
  return [{ json: { processar: false, resposta: { aceito: true, codigo: 'MENSAGEM_TEXTO_VAZIA' } } }];
}
if (tipo !== 'TEXTO' && !mediaId) {
  return [{ json: { processar: false, resposta: { aceito: true, codigo: 'MIDIA_SEM_MEDIA_ID', tipo } } }];
}

return [{
  json: {
    processar: true,
    payload: {
      mensagem_id: String(mensagem.id),
      wa_id: String(contato.wa_id ?? mensagem.from ?? ''),
      nome_contato: String(contato.profile?.name ?? ''),
      phone_number_id: String(value.metadata?.phone_number_id ?? ''),
      atendimento_id: String(atendimentoId),
      lead_id: String(leadId),
      texto,
      tipo,
      tipo_meta: tipoMeta,
      avaliacao_resposta: respostaBotao && avaliacaoBotaoPrefixo && respostaBotao.id.startsWith(avaliacaoBotaoPrefixo) ? respostaBotao : null,
      transferencia_lista_resposta: transferenciaListaResposta,
      followup_resposta: followupResposta,
      media: {
        id: mediaId,
        mime_type: String(conteudo.mime_type ?? ''),
        sha256: String(conteudo.sha256 ?? ''),
        filename: String(conteudo.filename ?? ''),
        caption: String(conteudo.caption ?? '')
      },
      recebido_em: mensagem.timestamp ? new Date(Number(mensagem.timestamp) * 1000).toISOString() : new Date().toISOString(),
      assinatura_meta_recebida: Boolean(headers['x-hub-signature-256'] ?? headers['X-Hub-Signature-256'])
    }
  }
}];

// Mantem o payload Meta como fonte principal e acrescenta somente contexto confirmado do CRM.
// O texto ja pode ter sido normalizado pelo EV-13 quando a mensagem original era midia.
const entrada = $('Normalizar Evolution para contrato legado').first().json;
const headers = entrada.headers ?? {};
const payload = $('Executar buffer mensagens').first().json.payload;

const lerHeader = (nome) => headers[nome] ?? headers[nome.toLowerCase()] ?? '';
const lerBooleano = (valor) => {
  const texto = String(valor ?? '').trim().toLowerCase();
  if (['true', '1', 'sim'].includes(texto)) return true;
  if (['false', '0', 'nao', 'não'].includes(texto)) return false;
  return null;
};

return [{
  json: {
    ...payload,
    atendimento_id: String(payload.atendimento_id || lerHeader('x-crm-atendimento-id')),
    lead_id: String(payload.lead_id || lerHeader('x-crm-lead-id')),
    crm_evento: String(lerHeader('x-crm-event')),
    atendimento_modo: String(lerHeader('x-crm-atendimento-modo')),
    dentro_horario_humano: lerBooleano(lerHeader('x-crm-dentro-horario')),
    ia_ativa: lerBooleano(lerHeader('x-crm-ia-ativa'))
  }
}];

