={{ (() => {
  // A existência da chave não basta: chaves antigas podem ainda ter TTL de sete dias.
  const valor = $('Buscar avaliacao pendente no Redis').first().json.avaliacao_pendente;
  if (!valor) return false;
  const segundos = $('Variaveis de producao').first().json.avaliacao_pendente_ttl_segundos;
  if (!Number.isInteger(segundos) || segundos <= 0) throw new Error('EV00_VALIDADE_AVALIACAO_INVALIDA');
  let pendencia;
  try { pendencia = typeof valor === 'string' ? JSON.parse(valor) : valor; }
  catch { return false; }
  // Sem início confiável, não consumir a mensagem do cliente como avaliação.
  const inicio = typeof pendencia?.iniciado_em === 'string' ? Date.parse(pendencia.iniciado_em) : NaN;
  const idade = Date.now() - inicio;
  // Aos 180 minutos exatos já está expirada. A mensagem segue para o buffer/IA.
  return Number.isFinite(inicio) && idade >= 0 && idade < segundos * 1000;
})() }}

